SET LOCAL search_path = public;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (322::BIGINT, 'Ni le escriban porque NO responde nunca. La participación grupal importa mucho porque si no se enoja. Deja asignaciones de un día para otro y casi siempre son confusas. Es una buena persona, pero no me parece un buen profesor.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2026-09-13T00:00:00+00:00'::TIMESTAMPTZ, '81d35284ba78dc853f2ae1590be814977111959dea174fd35737094c4ca5a746'::TEXT, ARRAY[1056]::BIGINT[]),
    (322::BIGINT, 'Mario es un asco de profesor. Todo el curso de diseño de software es accesibilidad, llegar a verle la cara y no aprender nada. Nunca explica, solo pasa las diapositivas cuando le da por dar clase. El resto es solo llegar uno a exponer lo que hizo y ver por qué no le gustó. No le ayuda a uno tampoco'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2026-08-04T00:00:00+00:00'::TIMESTAMPTZ, 'a2ad9db048c97415d39a5117ee69c9e3b28eefc7d1bdaabf428d23fc28d7f2ef'::TEXT, ARRAY[1047]::BIGINT[]),
    (322::BIGINT, 'El profe es muy buena nota y relajado, se nota que le gusta enseñar. Uno sí aprende en las clases. El problema es que a veces las presentaciones son medio enredadas y las instrucciones son confusas. Hay que exponer mucho y hacer bastante trabajo práctico.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Brinda apoyo']::TEXT[], '2026-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'd55a14067e3a670d9cb9d9ebbf72da3d0e101f7c5f81a9c4c21d739327e6a8f4'::TEXT, ARRAY[1039]::BIGINT[]),
    (322::BIGINT, 'Buen profesor, el curso es llevadero siempre y cuando usted me dedique tiempo, aunque no es mucho. Busque un buen equipo de proyecto y pasa fácil.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-10T00:00:00+00:00'::TIMESTAMPTZ, '1611ed226ba6741a258d611e44d9b60bb76dfd412f902631dc6296a6cd9aa158'::TEXT, ARRAY[1047]::BIGINT[]),
    (322::BIGINT, 'El curso es aburrido, ya que no ve nada de nuevas tecnologías, es como requerimientos, si no participan deja asignaciones, da buena retroalimentación pero solo en clase, cuesta que responda. Ve patrones de diseño como en 2 horas, cuando debería ser de eso el curso.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Asistencia obligatoria']::TEXT[], '2026-01-21T00:00:00+00:00'::TIMESTAMPTZ, 'f78ea7e9d74e5b414992cbb4c0edf1258c3547086678d38a705460e5dbe2c086'::TEXT, ARRAY[1047]::BIGINT[]),
    (322::BIGINT, 'Este semestre se le hizo un desmadre, no se sabía lo que pedía y luego le calificaba cosas que ni se mencionaron en clase. Por lo demás muy pesado el curso pero si le pregunta ayuda bastante.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2025-12-12T00:00:00+00:00'::TIMESTAMPTZ, 'bda3ace6a0aa7126b2c73eadff30942262dbb0b14b5c05733bf321b713edbfa5'::TEXT, ARRAY[1056]::BIGINT[]),
    (322::BIGINT, 'Me decepciono este semestre por completo, super desordenado, uno ni sabía que era lo que tenía que entregarle, no explicaba, las clases fue los estudiantes exponiendo, no aprendí casi nada.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Pocos exámenes']::TEXT[], '2025-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'fa3c22b2fc83da3e3b61e120441cc77756bc83a3d7aceb212298745186ca01ec'::TEXT, ARRAY[1056]::BIGINT[]),
    (322::BIGINT, 'Es una persona excelente pero como profesor deja que desear. Diseño es un curso muy importante y dejo temas como patrones de diseño, casi no contesta dudas, a veces deja en visto a los estudiantes.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2025-11-21T00:00:00+00:00'::TIMESTAMPTZ, '9698ca36eff4b0bd6c3553b65c6af10cc893d9510a16212638b408485e1b79a5'::TEXT, ARRAY[1047]::BIGINT[]),
    (322::BIGINT, 'Es buen profe, sabe muchísimo y uno aprende. Es duro sí, pero el curso no es duro si usted le hace preguntas y hace los trabajos con tiempo.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2025-07-24T00:00:00+00:00'::TIMESTAMPTZ, '69f49bd99e94c7f2ad370f098f0adfbff3aed0c34a159f589cb1bbdb9352f268'::TEXT, ARRAY[1056]::BIGINT[]),
    (322::BIGINT, 'En este curso es importante participar en las clases, hace tanto presenciales como virtuales. Si participan no deja tanto trabajo, los proyectos hace pre revisiones en llamada y va dando consejos sobre como mejorar el trabajo, así que cuando pida voluntarios, es mejor mandarse de una.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'b8e766618d7cc1dc47d7d53dfc43be9786a1fe63b42e4b2b6ef301fe87797567'::TEXT, ARRAY[1056]::BIGINT[]),
    (322::BIGINT, 'Es un profe muy amable, le gusta muchísimo que los estudiantes participen, aprendan y se equivoquen. Lo único negativo es que a veces se enreda con las presentaciones.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2025-07-04T00:00:00+00:00'::TIMESTAMPTZ, 'd60a887aaaed31e5f8f19707aa7d463b22ace955e7d8dd2999d3ba409153e1c3'::TEXT, ARRAY[1039]::BIGINT[]),
    (322::BIGINT, 'Mi opinion con Mario es dividida, cuando lleve con el en Reque fue un profe bastante bueno y comprensivo, pero ahora en Diseño fue otra cosa totalmente, especialmente en la forma que califico, en varias ocasiones le rebajo puntos a mi grupo sin razon alguna, poniendo excusas que nada que ver.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Brinda apoyo']::TEXT[], '2025-06-27T00:00:00+00:00'::TIMESTAMPTZ, '7e2f40291d7e9848a68760e4ebb8b015c7ac3c1cea58a9b4b95cefd660dc8b82'::TEXT, ARRAY[1047]::BIGINT[]),
    (322::BIGINT, 'Mario es de los profes que además de estudiantes forman personas. Él quiere que usted aprenda y le interese la clase. Es un profe excelente para requerimientos si no es que el mejor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2025-05-28T00:00:00+00:00'::TIMESTAMPTZ, 'be612bd99812f565f4a4e81e0bb0c2f009b83de8505f2f167500e4bd11b98fa4'::TEXT, ARRAY[1039]::BIGINT[]),
    (322::BIGINT, 'En general todo bien, la asistencia es obligatoria así que no queda de otra, al inicio no estuvieron muy claras unas evaluaciones aunque lo corrigió dentro del tiempo de entrega. A veces puede costar que responda una consulta.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2024-12-02T00:00:00+00:00'::TIMESTAMPTZ, '0c65e716ef52353bae272b8314c0bdb4476ba27043205a3fe1e15661599b7f8f'::TEXT, ARRAY[1039]::BIGINT[]),
    (322::BIGINT, 'Tiene que rogarle que califique los trabajos. El curso tiene mucho que dar y el mae simplemente no cumple'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2024-12-01T00:00:00+00:00'::TIMESTAMPTZ, '0436a18394e3554c5a66495384c5e921c5f16c545bb399010e75abf3135fca89'::TEXT, ARRAY[1047]::BIGINT[]),
    (322::BIGINT, 'Nos puso a hacer un proyecto de 20 personas para hacerle trabajo a una dependencia de la universidad, obviamente es un desastre total. Las clases son el mae leyendo un pdf de pura teoría para que luego tengas que hacer un proyecto web con tecnologías que el mae obliga a usar. Pésimo.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2024-10-16T00:00:00+00:00'::TIMESTAMPTZ, '5b4952c68a08ed4d2f9ef1d75fd340b76bc967e0412d3826a6bf8c9f3ddad7c0'::TEXT, ARRAY[1039]::BIGINT[]),
    (322::BIGINT, 'Agregó requisitos a un trabajo horas antes de entregarlo. Dice que todas las semanas hay quiz pero no los hace para que no se sepa si va a haber quiz o no. Es poco claro con las instrucciones de la progra y revisa los trabajos enfrente de toda la clase. No revisa casi nada hasta el final.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Clases largas']::TEXT[], '2024-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'a28d8316f45d677d47d10c7fbc26d4b1956e3f0c8a8cf61177a50180e86884bf'::TEXT, ARRAY[1047]::BIGINT[]),
    (322::BIGINT, 'El profe es muy pura vida y le gusta que los estudiantes participen en clase. Si es bastante desordenado con las asignaciones y en general no se aprende tanto en el curso como con otros profes.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, '2b76bc86077c93b962a3aee1e5a229daf09425c31c72f990fe394c310d28f91b'::TEXT, ARRAY[1047]::BIGINT[]),
    (322::BIGINT, 'Muy buen profe, en general le doy un 7.5/10. Los trabajos si se hacen con tiempo todo pura vida. En mi opinion se aprende mucho, lo unico que no me gusto fue que fue desordenado con las asignaciones.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2024-06-11T00:00:00+00:00'::TIMESTAMPTZ, '41171599b6aff339a34cb13cd2e0db7478d9435b74eaa983d8329157b1de3b9f'::TEXT, ARRAY[1039]::BIGINT[]),
    (322::BIGINT, 'El profesor es súper desordenado, pide cosas y ni siquiera se entienden, hay que rogarle para que sea claro. Hace quices sorpresa y en general, se aprende muy muy poco, si quiere aprender diseño de software, este no es el profesor. Eso sí, los cursos son fáciles de pasar.'::TEXT, 10.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'La participación importa', 'Clases largas']::TEXT[], '2024-05-22T00:00:00+00:00'::TIMESTAMPTZ, 'b3c966dcdeab8b10a62147d465f0ae54866336b9695824a6f132a0b4e619eb0c'::TEXT, ARRAY[1047]::BIGINT[]),
    (322::BIGINT, 'Es desordenado con las evaluaciones y con su revisión, sin embargo la rúbrica es exacta y califica suave. A veces pierde el hilo en las clases y conocimiento técnico como tal explica muy poco, pero es muy buena persona y trata de ejemplificar con contextos reales.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador', 'Clases largas']::TEXT[], '2023-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'ee722ad72a5c9ad07d045fa81469dcc390b683edc8e8b0ebf7aaf417143f233e'::TEXT, ARRAY[1039]::BIGINT[]),
    (322::BIGINT, 'Se siente que nunca tiene las clases preparadas, no es claro con fechas y es un irresponsable con las evaluaciones. Como nunca asignó los trabajos que había propuesto, repartió la nota como quiso sin preguntarle a nadie. No matricule con él, no va a aprender nada y se va a arrepentir cada instante.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'e0508e6e0bfaf213768eed2be2860d3b6290d88cdbcec8c5ea56db59af499274'::TEXT, ARRAY[1056]::BIGINT[]),
    (322::BIGINT, 'No vale la pena Un mega trabajo al final de clase para que califique cosas que no tienen sentido Evítenlo , esto curso no se trata de programar ni aprender . Parece un curso CFH que otra cosa , mucho brete al final para un curso tan muerto'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'f2fd42a4005a67790525b13aa85cd6a9008fd94ec903eacef7317aa5ff29c5f4'::TEXT, ARRAY[1039]::BIGINT[]),
    (322::BIGINT, 'Durante las clases se dispersa mucho y uno se termina perdiendo entre tanto tema, las clases son largas y aburridas. Es muchísimo trabajo para un curso que solo vale 3 créditos, aparte no atiende dudas fuera de la clase. Es muy estricto con la asistencia. Casi todo el trabajo es grupal.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, '97f8d702d18c949b36f74240019fb929c555f1b674f2e277e7d259347128a264'::TEXT, ARRAY[1056]::BIGINT[]),
    (322::BIGINT, 'Muchísimo brete a lo largo del semestre. Casi todos los trabajos fueron documentos escritos. Si tiene cierto número de tardías pierde el curso. La última parte del curso fueron exposiciones de los compañeros. Califica duro con la ortografía. Si el grupo no está fino con la materia puede hacer quiz.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Muchos proyectos grupales']::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'ad7d453b725ef427f9558183f4494d077d2a5b2565752cffc6d36861868ac77b'::TEXT, ARRAY[1056]::BIGINT[]),
    (322::BIGINT, 'Es un profe muy pura vida, no tiene problema con mover fechas de trabajos. Sí se desvía un poco de lo que se debería ver en el curso pero se aprenden cosas que no se verían en otro lado, es importante que como grupo participen y respondan para que él vea el interés, quices a cuaderno abierto.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador', 'Pocos exámenes']::TEXT[], '2022-11-09T00:00:00+00:00'::TIMESTAMPTZ, 'df874a93ff320f01c8a16ed531c2a0112641752464926a9f6fbe66e3b210c9a0'::TEXT, ARRAY[1047]::BIGINT[]),
    (322::BIGINT, 'Las clases son muy participativas y siempre hay bastante retroalimentacion, lado negativo es que no se vieorns temas que esperaría en el curso, se le da mucha importancia a diagramas/interfaces y accesibilidad, y no se ve casi nada de patrones de diseño (es solo un trabajo en todo el semestre)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '69734a329fa931e8ba9f76fbe7ec17cf187592bb6dfee8544fc8b89a56b4feed'::TEXT, ARRAY[1047]::BIGINT[]),
    (322::BIGINT, 'En requi el profe estuvo súper bien organizado. Pero en diseño el planeamiento del cursos se sentía demasiado desorganizado sin mucha claridad de lo que se veía o se entregaba.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Muchos proyectos grupales']::TEXT[], '2022-05-24T00:00:00+00:00'::TIMESTAMPTZ, 'f4d201f84998bee23789c6a9f3ac42395e725e3ce3f9d1d8ceedda4d18733ba7'::TEXT, ARRAY[1047]::BIGINT[]),
    (322::BIGINT, 'El profesor organizó el curso muy bien, todo lo tenía planeado, se le puede preguntar sin problemas, se hace un proyecto que se va armando a lo largo del semestre y con feedback de él. Buenísimo, recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-09T00:00:00+00:00'::TIMESTAMPTZ, '30513efbe1f156153eada50f424edb2e8c2c9544dc59502eb1a9eea634912f0f'::TEXT, ARRAY[1039]::BIGINT[]),
    (322::BIGINT, 'Buen profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-08-12T00:00:00+00:00'::TIMESTAMPTZ, '803698eff5a597e290ef57e0eea9652667e82318f09993201f96c2906f5c8c3e'::TEXT, ARRAY[1039]::BIGINT[]),
    (322::BIGINT, 'De diseño se aprende poco ó nada.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2021-07-28T00:00:00+00:00'::TIMESTAMPTZ, 'c9e3c85f43af2f0dbd57e248c1ea234739ada835f5f1f091bbde698f2454e73c'::TEXT, ARRAY[1047]::BIGINT[]),
    (322::BIGINT, 'Fácil el peor profesor que he tenido en la carrera. Cree que el curso es de diseño gráfico, no de diseño de software. De diseño de software no enseña nada. Su unico fuerte es accesibilidad del software. Irrespetuoso, colerico, ambiguo con los trabajos y flexible con fechas de entrega.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2021-07-22T00:00:00+00:00'::TIMESTAMPTZ, '411ada45a3c290de81d3f872bf5a0f7fd97355bbf7ab157cd868b1a6f7f35ffe'::TEXT, ARRAY[1047]::BIGINT[]),
    (322::BIGINT, 'Deja muchos trabajos, las clases son largas y si no hay participación haces quices, pasa lista al inicio de la clase. No se ve la materia que se debería ver, además no diría que es fácil de pasar, es bastante pesado el curso.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2021-07-08T00:00:00+00:00'::TIMESTAMPTZ, 'd3536ca1e5a902efe2eef3f47e42aa63122edb44fe7f7b2cfb815993db7c14e1'::TEXT, ARRAY[1047]::BIGINT[]),
    (322::BIGINT, 'Si quieren aprender algo, no metan nada con este profesor. El peor profesor que he tenido en la carrera, si quisiera aprender diseño gráfico no me hubiera metido a compu. Pero no se engañen, que tampoco aprendí diseño gráfico. No aprendí NADA.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2021-07-07T00:00:00+00:00'::TIMESTAMPTZ, '2b7fa60017e91614955e1d4155aca5b6f2441ce12ff468e7d652cf0e14fe4e49'::TEXT, ARRAY[1047]::BIGINT[]),
    (322::BIGINT, 'Fácilmente el peor profesor de la escuela. Se ven colores y accesibilidad casi todo el semestre, básicamente no sabe que curso está dando. Califica suave, baja puntos por tonteras y no se aprende nada. Lo mejor que puede hacer es no matricular con él, simplemente una pérdida de tiempo.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-06T00:00:00+00:00'::TIMESTAMPTZ, '75183f4785e24918be7042fdb30e387f743ef2cc601c485f0593e897e94a2d18'::TEXT, ARRAY[1047]::BIGINT[]),
    (322::BIGINT, 'Entre el top 3 de los peores profes de compu, todo los trabajos los revisa el asistente, hay cero comunicación entre el profe y el asistente que hace lo que le da la gana, al final el profe le da la razón al asistente sobre cualquier reclamó que se le haga'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Deja trabajos largos']::TEXT[], '2021-07-02T00:00:00+00:00'::TIMESTAMPTZ, 'ab0f9170df49dae3a03cab269df768543b5e01a74f7f30d5911b0e78b45ecd46'::TEXT, ARRAY[1047]::BIGINT[]),
    (322::BIGINT, 'Es fundamental que participen en clases, le gusta mucho que pregunten sobre el tema sino amenaza con hacer quices, lo cual es molesto porque las clases son aburridas, habla mucho sobre accesibilidad, se llevo 1.5 semanas hablando sobre eso y los patrones de diseño de interfaz lo vio en una clase.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2021-04-26T00:00:00+00:00'::TIMESTAMPTZ, 'a0be401b9b215eaa9359706e0ee94f03d5a2e1e091d39acb3910c7cb266b565c'::TEXT, ARRAY[1047]::BIGINT[]),
    (322::BIGINT, 'Le gusta la participación al punto que se enoja si nadie participa, hace comentario como amenazantes de que como nadie participa el tema va para quiz o comentarios de "como andan tan participativos..." y eso molesta, pero es buen profe, buena nota, ayuda mucho, pero cuesta mucho ponerle atención'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2021-04-21T00:00:00+00:00'::TIMESTAMPTZ, '983eb4254a0850927ddd0c4d173e07873ef71f122508ef23ba9ecfdc970117ba'::TEXT, ARRAY[1047]::BIGINT[]),
    (322::BIGINT, 'Realmente no se dedica a seguir el 80% de lo dicho en el plan de curso y si lo hace, lo hace de forma muy superficial. Sin importar el curso que se lleve le mete temas de accesibilidad hasta decir basta, no lo toca como un tema normal sino que lo trata durante todo el semestre.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Clases largas']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '9eb4ee0a41b055113ada866b9d2bb5b9bac2c38aa7a2ea1d5350578db90f97dc'::TEXT, ARRAY[1047]::BIGINT[]),
    (322::BIGINT, 'Muy estricto con las entregas de los trabajos, se realizan pocos quices y tareas. Le gusta que los estudiantes esten participando en la clase.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '5d251ed7bf11ed5af5bbcb1769dc880f24f4d133519a701f40b44a963ca4a9e3'::TEXT, ARRAY[1047]::BIGINT[]),
    (322::BIGINT, 'Fácil de pasar con él en este curso. No se hacen exámenes y casi no hay quices. Le gusta que los estudiantes participen en su clase. Pero es muy llevadero. Es muy estricto con la puntualidad, pasa lista apenas inicia la clase.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2020-08-09T00:00:00+00:00'::TIMESTAMPTZ, 'c883a63d2db6a2bbcaf29eac016b2053a99ecdf841b62917cb240ef8880ba4ea'::TEXT, ARRAY[1047]::BIGINT[]),
    (322::BIGINT, 'El profe hizo un proyecto en grupos de 10 lo cual es complicado de organizar. Se aprendió bastante acerca de trabajo en equipo, pero las clases son desorganizadas y sí, habla mucho de su experiencia laboral. Se aprende mucho por el approach "vida real", pero la carga de trabajo fue muchísima.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2020-02-04T00:00:00+00:00'::TIMESTAMPTZ, '0842f336780849fa5746a0ae3b8b3f8f854b064c17f285e88729d42079325ca0'::TEXT, ARRAY[1039]::BIGINT[]),
    (322::BIGINT, 'El tipo no sabe de que está hablando, paso todo el semestre amenazándonos y al final no enseño nada, TOP 10 malos profes en compu'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-03T00:00:00+00:00'::TIMESTAMPTZ, '16fa6e72acd0e01ba59ad51978d8d660994a2dd2cc7f0c8a1c52140f7ebd415e'::TEXT, ARRAY[1039]::BIGINT[]),
    (322::BIGINT, 'No abarca la materia por hablar acerca de sus experiencias laborales.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2020-01-25T00:00:00+00:00'::TIMESTAMPTZ, '45dcdccf25579af2d16dddcdccc6900d6778004df20fb37cc392c19144d7fc5b'::TEXT, ARRAY[1039]::BIGINT[]),
    (322::BIGINT, 'Durante el curso el profesor trató de brindar una experiencia lo más cercana al trabajo en la calle con interacción con clientes y demás. A costa de esto no pudimos ver buena parte de la materia. Sin embargo, los trabajos son interesantes, fomenta la competitividad entre grupos y trabajo en equipo.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2019-12-28T00:00:00+00:00'::TIMESTAMPTZ, '7b798f54ceef1942b2b00945a1f90e6a81083be4e014580309da0aae1ad5dd35'::TEXT, ARRAY[1039]::BIGINT[]),
    (322::BIGINT, 'Un señor bastante lleno de estereotipos, tanto clasistas como homofóbicos, y de vez en cuando se le sale lo onvre. Usa las clases para contar sus experiencias laborales y es algo desordenado con la materia.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas']::TEXT[], '2019-12-17T00:00:00+00:00'::TIMESTAMPTZ, '0796664c15cceff2b30ba2e56c4c7158f816204b95a257d9748c993dcd28da3b'::TEXT, ARRAY[1039]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
